mod definitions;
mod merkle_tree;

use poseidon::poseidon2::Poseidon2::hash;

global DEPTH: u32 = 2;

fn main(
    root: pub Field,
    path: [Field; DEPTH],
    direction_selector: [bool; DEPTH],
    secret: Field,
    priv_key: Field,
    voter_id: pub Field, // Same for all votes in this proposal
    nullifier: pub Field, // Unique per option
    proposal_id: pub Field,
    option: pub u8, // Which option (0, 1, 2, 3, ...)
    vote_strength: pub u8, // Vote strength for THIS option
) {
    let note_commitment = definitions::commitment(priv_key, secret);

    merkle_tree::assert_merkle_inclusion(
        root,
        path,
        direction_selector,
        note_commitment,
        "Commitment not in Merkle Tree",
    );

    // Verify voter_id is correctly derived from private key
    assert(voter_id == definitions::voter_id(root, priv_key, proposal_id), "Invalid voter_id");

    // Verify nullifier is correctly derived from voter_id + option
    assert(nullifier == definitions::nullifier(voter_id, option), "Invalid nullifier");

    // Validate vote strength
    assert(vote_strength >= 1, "Must vote at least 1");
    assert(vote_strength <= 10, "Max vote strength is 10");
}

#[test]
fn test_single_option_vote() {
    let priv_key = 123456789;
    let secret = 987654321;
    let proposal_id = 1;
    let option = 0; // Vote on option A
    let vote_strength = 5; // Cost = 25 credits

    let note_commitment = definitions::commitment(priv_key, secret);

    let sibling = definitions::commitment(0, 0);
    let left_branch = hash([note_commitment, sibling], 2);
    let right_branch = hash([sibling, sibling], 2);
    let root = hash([left_branch, right_branch], 2);

    let path = [sibling, right_branch];
    let direction_selector = [false, false];

    let voter_id = definitions::voter_id(root, priv_key, proposal_id);
    let nullifier = definitions::nullifier(voter_id, option);

    main(
        root,
        path,
        direction_selector,
        secret,
        priv_key,
        voter_id,
        nullifier,
        proposal_id,
        option,
        vote_strength,
    );
}

#[test]
fn test_multiple_options_same_voter() {
    // Bob votes on options A (5), B (3), C (2)
    // Total cost: 25 + 9 + 4 = 38 credits (under 100 limit)
    let priv_key = 555666777;
    let secret = 111222333;
    let proposal_id = 1;

    let note_commitment = definitions::commitment(priv_key, secret);
    let sibling = definitions::commitment(0, 0);
    let left_branch = hash([note_commitment, sibling], 2);
    let right_branch = hash([sibling, sibling], 2);
    let root = hash([left_branch, right_branch], 2);

    let path = [sibling, right_branch];
    let direction_selector = [false, false];
    let voter_id = definitions::voter_id(root, priv_key, proposal_id);

    // Vote on option A (strength 5)
    let nullifier_a = definitions::nullifier(voter_id, 0);
    main(
        root,
        path,
        direction_selector,
        secret,
        priv_key,
        voter_id,
        nullifier_a,
        proposal_id,
        0,
        5,
    );

    // Vote on option B (strength 3)
    let nullifier_b = definitions::nullifier(voter_id, 1);
    main(
        root,
        path,
        direction_selector,
        secret,
        priv_key,
        voter_id,
        nullifier_b,
        proposal_id,
        1,
        3,
    );

    // Vote on option C (strength 2)
    let nullifier_c = definitions::nullifier(voter_id, 2);
    main(
        root,
        path,
        direction_selector,
        secret,
        priv_key,
        voter_id,
        nullifier_c,
        proposal_id,
        2,
        2,
    );

    // Note: Contract must verify total cost (25+9+4=38) <= 100
}

#[test(should_fail_with = "Must vote at least 1")]
fn test_invalid_vote_strength() {
    let priv_key = 123456789;
    let secret = 987654321;
    let proposal_id = 1;
    let option = 0;
    let vote_strength = 0; // Invalid: must be at least 1

    let note_commitment = definitions::commitment(priv_key, secret);
    let sibling = definitions::commitment(0, 0);
    let left_branch = hash([note_commitment, sibling], 2);
    let right_branch = hash([sibling, sibling], 2);
    let root = hash([left_branch, right_branch], 2);

    let path = [sibling, right_branch];
    let direction_selector = [false, false];
    let voter_id = definitions::voter_id(root, priv_key, proposal_id);
    let nullifier = definitions::nullifier(voter_id, option);

    main(
        root,
        path,
        direction_selector,
        secret,
        priv_key,
        voter_id,
        nullifier,
        proposal_id,
        option,
        vote_strength,
    );
}

#[test(should_fail_with = "Invalid voter_id")]
fn test_invalid_voter_id() {
    let priv_key = 123456789;
    let secret = 987654321;
    let proposal_id = 1;
    let option = 0;
    let vote_strength = 5;

    let note_commitment = definitions::commitment(priv_key, secret);
    let sibling = definitions::commitment(0, 0);
    let left_branch = hash([note_commitment, sibling], 2);
    let right_branch = hash([sibling, sibling], 2);
    let root = hash([left_branch, right_branch], 2);

    let path = [sibling, right_branch];
    let direction_selector = [false, false];

    // Wrong voter_id (using wrong proposal_id)
    let wrong_voter_id = definitions::voter_id(root, priv_key, proposal_id + 1);
    let nullifier = definitions::nullifier(wrong_voter_id, option);

    main(
        root,
        path,
        direction_selector,
        secret,
        priv_key,
        wrong_voter_id,
        nullifier,
        proposal_id,
        option,
        vote_strength,
    );
}

#[test(should_fail_with = "Invalid nullifier")]
fn test_invalid_nullifier() {
    let priv_key = 123456789;
    let secret = 987654321;
    let proposal_id = 1;
    let option = 0;
    let vote_strength = 5;

    let note_commitment = definitions::commitment(priv_key, secret);
    let sibling = definitions::commitment(0, 0);
    let left_branch = hash([note_commitment, sibling], 2);
    let right_branch = hash([sibling, sibling], 2);
    let root = hash([left_branch, right_branch], 2);

    let path = [sibling, right_branch];
    let direction_selector = [false, false];
    let voter_id = definitions::voter_id(root, priv_key, proposal_id);

    // Wrong nullifier (using wrong option)
    let wrong_nullifier = definitions::nullifier(voter_id, option + 1);

    main(
        root,
        path,
        direction_selector,
        secret,
        priv_key,
        voter_id,
        wrong_nullifier,
        proposal_id,
        option,
        vote_strength,
    );
}

